30	/**
31	 * @brief CumSum核函数类，实现按行或列进行累加和操作
32	 * @tparam T 输入输出数据类型
33	 * @tparam CONFIG CumSum配置参数
34	 */
35	template <typename T, const AscendC::CumSumConfig& CONFIG>
36	class KernelCumSum {
37	public:
38	    __aicore__ inline KernelCumSum() {}
39	    __aicore__ inline void Init(
40	        __gm__ uint8_t* srcGm, __gm__ uint8_t* dstGm, __gm__ uint8_t* lastRowGm, uint32_t outter, uint32_t inner,
41	        uint32_t gmOutter, uint32_t gmInner, uint32_t tmpBufSize, AscendC::TPipe* tPipe)
42	    {
43	        this->outter = outter;
44	        this->inner = inner;
45	        this->gmOutter = gmOutter;
46	        this->gmInner = gmInner;
47	        this->pipe = tPipe;
48	
49	        srcGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(srcGm), this->gmOutter * this->gmInner);
50	        dstGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(dstGm), this->gmOutter * this->gmInner);
51	        lastRowGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(lastRowGm), this->gmInner);
52	
53	        this->pipe->InitBuffer(inQueueX, BUFFER_NUM, Align32B<T>(outter * inner) * sizeof(T));
54	        this->pipe->InitBuffer(outQueue, BUFFER_NUM, Align32B<T>(outter * inner) * sizeof(T));
55	        this->pipe->InitBuffer(lastRowQueue, BUFFER_NUM, Align32B<T>(inner) * sizeof(T));
56	        this->pipe->InitBuffer(buf, tmpBufSize * sizeof(uint8_t));
57	    }
58	    __aicore__ inline void Process()
59	    {
60	        CopyIn();
61	        Compute();
62	        CopyOut();
63	    }
64	
65	private:
66	    __aicore__ inline void CopyIn()
67	    {
68	        AscendC::LocalTensor<T> srcLocal = inQueueX.AllocTensor<T>();
69	        AscendC::DataCopyPadParams dataCopyPadParams;
70	        for (int32_t i = 0; i < gmOutter; i++) {
71	            AscendC::DataCopyPad(
72	                srcLocal[i * inner], srcGlobal[i * gmInner], {1, static_cast<uint16_t>(gmInner * sizeof(T)), 0, 0},
73	                dataCopyPadParams);
74	        }
75	
76	        inQueueX.EnQue(srcLocal);
77	    }
78	    __aicore__ inline void Compute()
79	    {
80	        AscendC::LocalTensor<T> dstLocal = outQueue.AllocTensor<T>();
81	        AscendC::LocalTensor<T> lastRowLocal = lastRowQueue.AllocTensor<T>();
82	        AscendC::LocalTensor<T> srcLocal = inQueueX.DeQue<T>();
83	        AscendC::LocalTensor<uint8_t> sharedTmpBuffer = buf.Get<uint8_t>();
84	        // outter：输入数据的外轴长度
85	        // inner： 输入数据的内轴长度
86	        const AscendC::CumSumInfo cumSumInfo{outter, inner};
87	        // 使用CumSum高阶API进行累加和计算
88	        // 模板参数：
89	        //   - T: 输入输出数据类型
90	        //   - CONFIG: CumSum配置参数，包含axis、isReverse等
91	        // 参数说明：
92	        //   - dstLocal: 输出Tensor，存储累加结果
93	        //   - lastRowLocal: 最后一行结果Tensor
94	        //   - srcLocal: 输入Tensor
95	        //   - sharedTmpBuffer: 临时空间
96	        //   - cumSumInfo: 累加配置信息（outter, inner）
97	        AscendC::CumSum<T, CONFIG>(dstLocal, lastRowLocal, srcLocal, sharedTmpBuffer, cumSumInfo);
98	        outQueue.EnQue<T>(dstLocal);
99	        lastRowQueue.EnQue<T>(lastRowLocal);
100	        inQueueX.FreeTensor(srcLocal);
101	    }
102	    __aicore__ inline void CopyOut()
103	    {
104	        AscendC::LocalTensor<T> dstLocal = outQueue.DeQue<T>();
105	        for (int32_t i = 0; i < gmOutter; i++) {
106	            AscendC::DataCopyPad(
107	                dstGlobal[i * gmInner], dstLocal[i * inner], {1, static_cast<uint16_t>(gmInner * sizeof(T)), 0, 0});
108	        }
109	        outQueue.FreeTensor(dstLocal);
110	        AscendC::LocalTensor<T> lastRowLocal = lastRowQueue.DeQue<T>();
111	        AscendC::DataCopyPad(lastRowGlobal, lastRowLocal, {1, static_cast<uint16_t>(gmInner * sizeof(T)), 0, 0});
112	        lastRowQueue.FreeTensor(lastRowLocal);
113	    }
114	
115	private:
116	    AscendC::GlobalTensor<T> srcGlobal;
117	    AscendC::GlobalTensor<T> dstGlobal;
118	    AscendC::GlobalTensor<T> lastRowGlobal;
119	
120	    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inQueueX;
121	    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outQueue;
122	    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> lastRowQueue;
123	    AscendC::TBuf<AscendC::QuePosition::VECCALC> buf;
124	
125	    AscendC::TPipe* pipe;
126	
127	    uint32_t outter{1};
128	    uint32_t inner{1};
129	    uint32_t gmOutter{1};
130	    uint32_t gmInner{1};
131	};
