151	static bool CompareResult(const void* outputData, int64_t outSize, std::string goldenName)
152	{
153	    void* goldenData;
154	    aclrtMallocHost((void**)(&goldenData), outSize);
155	    size_t goldenSize = outSize;
156	    bool ret = ReadFile("./output/golden_output_" + goldenName + ".bin", goldenSize, goldenData, goldenSize);
157	    if (ret) {
158	        printf("ReadFile golden_output_%s.bin success!\n", goldenName.c_str());
159	    } else {
160	        aclrtFreeHost(goldenData);
161	        return false;
162	    }
163	    constexpr float EPS = 1e-5;
164	    int64_t wrongNum = 0;
165	
166	    for (int i = 0; i < outSize / sizeof(float); i++) {
167	        float a = (reinterpret_cast<const float*>(outputData))[i];
168	        float b = (reinterpret_cast<const float*>(goldenData))[i];
169	        float ae = std::abs(a - b);
170	        float re = ae / std::abs(b);
171	        if (ae > EPS && re > EPS) {
172	            printf(
173	                "CompareResult golden_output_%s.bin failed output is %lf, golden is %lf\n", goldenName.c_str(), a, b);
174	            wrongNum++;
175	        }
176	    }
177	    aclrtFreeHost(goldenData);
178	    if (wrongNum != 0) {
179	        return false;
180	    } else {
181	        printf("CompareResult golden_output_%s.bin success!\n", goldenName.c_str());
182	        return true;
183	    }
184	}
