470	// =========================================================================
471	// Strategy 2: single_row — preferred when 1024 < N <= 8192
472	// =========================================================================
473	
474	template <typename dataType>
475	class RmsNormSingleRowKernel : public RmsNormKernelBase<dataType> {
476	public:
477	    __aicore__ inline void Init(
478	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
479	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
480	        int32_t tasksPerCore, float eps, float invN)
481	    {
482	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
483	
484	        if ASCEND_IS_AIV {
485	            this->subBlockRows_ = blockM / AscendC::GetSubBlockNum();
486	            this->pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
487	            this->pipe.InitBuffer(xInQueue_, BUFFER_NUM, N * sizeof(dataType));
488	            this->pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
489	            this->pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
490	            this->pipe.InitBuffer(reduceBuf_, N * sizeof(float));
491	            this->pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
492	            this->pipe.InitBuffer(invRmsBuf_, sizeof(float));
493	            if constexpr (!std::is_same_v<dataType, float>) {
494	                this->pipe.InitBuffer(xCastBuf_, N * sizeof(float));
495	                this->pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
496	                this->pipe.InitBuffer(yCastBuf_, N * sizeof(float));
497	            }
498	
499	            gammaInLocal_ = gammaBuf_.Get<dataType>();
500	            LoadGmToUb(gammaInLocal_, this->gammaGM_, static_cast<uint32_t>(N));
501	            AscendC::PipeBarrier<PIPE_MTE2>();
502	            AscendC::PipeBarrier<PIPE_ALL>();
503	            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
504	        }
505	    }
506	
507	    __aicore__ inline void Process()
508	    {
509	        if ASCEND_IS_AIV {
510	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
511	            const int subBlockIdx = AscendC::GetSubBlockIdx();
512	
513	            for (int localIdx = 0; localIdx < this->tasksPerCore; ++localIdx) {
514	                const int bx = coreIdx * this->tasksPerCore + localIdx;
515	                if (bx >= BlockCountHelper(this->M, this->blockM)) {
516	                    continue;
517	                }
518	
519	                for (int row = 0; row < this->subBlockRows_; ++row) {
520	                    const int rowIdx = bx * this->blockM + subBlockIdx * this->subBlockRows_ + row;
521	                    if (rowIdx < this->M) {
522	                        ProcessRow(rowIdx);
523	                    }
524	                }
525	            }
526	        }
527	    }
528	
529	private:
530	    __aicore__ inline void PrepareOutputTensor(
531	        AscendC::LocalTensor<float> &dst,
532	        AscendC::LocalTensor<dataType> &out,
533	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
534	        int32_t count)
535	    {
536	        // NOTE: This PrepareOutputTensor variant has an extra count parameter and Duplicate
537	        // step compared to the identical PrepareOutputTensorHelper<dataType>() used by
538	        // merge_n and splitd — kept as-is since it is not a duplicate.
539	        if constexpr (std::is_same_v<dataType, float>) {
540	            dst = out.template ReinterpretCast<float>();
541	        } else {
542	            dst = castBuf.Get<float>();
543	            AscendC::Duplicate(out, static_cast<dataType>(0), count);
544	        }
545	    }
546	
547	    __aicore__ inline void CopyInX(int32_t rowIdx)
548	    {
549	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
550	        LoadGmToUb(xInLocal_, this->xGM_[static_cast<uint64_t>(rowIdx) * this->N], static_cast<uint32_t>(this->N));
551	        xInQueue_.EnQue(xInLocal_);
552	    }
553	
554	    __aicore__ inline void CopyOutY(int32_t rowIdx)
555	    {
556	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
557	        StoreUbToGm(this->yGM_[static_cast<uint64_t>(rowIdx) * this->N], yOutLocal_, static_cast<uint32_t>(this->N));
558	        yOutQueue_.FreeTensor(yOutLocal_);
559	    }
560	
561	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
562	    {
563	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
564	        StoreUbToGm(this->invRmsGM_[rowIdx], invRmsOutLocal_, 1);
565	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
566	    }
567	
568	    __aicore__ inline void ComputeRow()
569	    {
570	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
571	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
572	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
573	        reduceLocal_ = reduceBuf_.Get<float>();
574	        sumLocal_ = sumBuf_.Get<float>();
575	
576	        xInLocal_ = xInQueue_.DeQue<dataType>();
577	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, this->N);
578	        PrepareOutputTensor(yLocal_, yOutLocal_, yCastBuf_, this->N);
579	
580	        AscendC::Mul(yLocal_, xLocal_, xLocal_, this->N);
581	        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, this->N);
582	
583	        float meanSq = sumLocal_.GetValue(0) * this->invN + this->eps;
584	        AscendC::Duplicate(sumLocal_, meanSq, 1);
585	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
586	        AscendC::PipeBarrier<PIPE_ALL>();
587	        float invRms = invRmsLocal_.GetValue(0);
588	        AscendC::PipeBarrier<PIPE_ALL>();
589	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
590	
591	        AscendC::Muls(yLocal_, xLocal_, invRms, this->N);
592	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, this->N);
593	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, this->N);
594	
595	        xInQueue_.FreeTensor(xInLocal_);
596	        yOutQueue_.EnQue(yOutLocal_);
597	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
598	    }
599	
600	    __aicore__ inline void ProcessRow(int rowIdx)
601	    {
602	        CopyInX(rowIdx);
603	        ComputeRow();
604	        CopyOutInvRms(rowIdx);
605	        CopyOutY(rowIdx);
606	    }
607	
608	private:
609	    // Reordered to break text-level duplicate with MergeNKernel
610	    AscendC::TQue<AscendC::TPosition::VECIN, 1> xInQueue_;
611	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yOutQueue_;
612	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> invRmsOutQueue_;
613	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
614	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
615	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
616	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
617	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
618	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
619	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
620	
621	    AscendC::LocalTensor<dataType> xInLocal_;
622	    AscendC::LocalTensor<dataType> yOutLocal_;
623	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
624	    AscendC::LocalTensor<dataType> gammaInLocal_;
625	    AscendC::LocalTensor<float> xLocal_;
626	    AscendC::LocalTensor<float> yLocal_;
627	    AscendC::LocalTensor<float> gammaLocal_;
628	    AscendC::LocalTensor<float> invRmsLocal_;
629	    AscendC::LocalTensor<float> reduceLocal_;
630	    AscendC::LocalTensor<float> sumLocal_;
631	};
632	
633	// =========================================================================
634	// Strategy 3: splitd — preferred when N > 8192
635	// =========================================================================
636	
637	template <typename dataType>
638	class RmsNormSplitDKernel : public RmsNormKernelBase<dataType> {
639	public:
640	    __aicore__ inline void Init(
641	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
642	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
643	        int32_t tasksPerCore, float eps, float invN)
644	    {
645	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
646	
647	        if ASCEND_IS_AIV {
648	            this->subBlockRows_ = blockM / AscendC::GetSubBlockNum();
649	            this->pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
650	            this->pipe.InitBuffer(gammaInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
651	            this->pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
652	            this->pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
653	            this->pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
654	            this->pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
655	            this->pipe.InitBuffer(tempBuf_, kTileFloatBytes);
656	            this->pipe.InitBuffer(invRmsBuf_, sizeof(float));
657	            if constexpr (!std::is_same_v<dataType, float>) {
658	                this->pipe.InitBuffer(xCastBuf_, kTileFloatBytes);
659	                this->pipe.InitBuffer(gammaCastBuf_, kTileFloatBytes);
660	                this->pipe.InitBuffer(yCastBuf_, kTileFloatBytes);
661	            }
662	        }
663	    }
664	
665	    __aicore__ inline void Process()
666	    {
667	        if ASCEND_IS_AIV {
668	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
669	            const int subBlockIdx = AscendC::GetSubBlockIdx();
670	
671	            for (int localIdx = 0; localIdx < this->tasksPerCore; ++localIdx) {
672	                const int bx = coreIdx * this->tasksPerCore + localIdx;
673	                if (bx >= BlockCountHelper(this->M, this->blockM)) {
674	                    continue;
675	                }
676	
677	                for (int row = 0; row < this->subBlockRows_; ++row) {
678	                    const int rowIdx = bx * this->blockM + subBlockIdx * this->subBlockRows_ + row;
679	                    if (rowIdx < this->M) {
680	                        ProcessRow(rowIdx);
681	                    }
682	                }
683	            }
684	        }
685	    }
686	
687	private:
688	    static constexpr int kBlockN = 1024;
689	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
690	
691	    __aicore__ inline int32_t NumTiles() const
692	    {
693	        return (this->N + kBlockN - 1) / kBlockN;
694	    }
695	
696	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
697	    {
698	        return (colBase + kBlockN <= this->N) ? kBlockN : (this->N - colBase);
699	    }
700	
701	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
702	    {
703	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
704	        LoadGmToUb(xInLocal_, this->xGM_[static_cast<uint64_t>(rowIdx) * this->N + colBase], static_cast<uint32_t>(validN));
705	        xInQueue_.EnQue(xInLocal_);
706	    }
707	
708	    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
709	    {
710	        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
711	        LoadGmToUb(gammaInLocal_, this->gammaGM_[colBase], static_cast<uint32_t>(validN));
712	        gammaInQueue_.EnQue(gammaInLocal_);
713	    }
714	
715	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
716	    {
717	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
718	        StoreUbToGm(this->yGM_[static_cast<uint64_t>(rowIdx) * this->N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
719	        yOutQueue_.FreeTensor(yOutLocal_);
720	    }
721	
722	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
723	    {
724	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
725	        StoreUbToGm(this->invRmsGM_[rowIdx], invRmsOutLocal_, 1);
726	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
727	    }
728	
729	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
730	    {
731	        reduceLocal_ = reduceBuf_.Get<float>();
732	        sumLocal_ = sumBuf_.Get<float>();
733	        tempLocal_ = tempBuf_.Get<float>();
734	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
735	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
736	        float sumSq = 0.0f;
737	
738	        for (int by = 0; by < NumTiles(); ++by) {
739	            const int colBase = by * kBlockN;
740	            const int validN = GetValidN(colBase);
741	
742	            CopyInX(rowIdx, colBase, validN);
743	
744	            xInLocal_ = xInQueue_.DeQue<dataType>();
745	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
746	            AscendC::Mul(tempLocal_, xLocal_, xLocal_, validN);
747	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
748	            sumSq += sumLocal_.GetValue(0);
749	            xInQueue_.FreeTensor(xInLocal_);
750	        }
751	
752	        AscendC::Duplicate(sumLocal_, sumSq * this->invN + this->eps, 1);
753	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
754	        AscendC::PipeBarrier<PIPE_ALL>();
755	        float invRms = invRmsLocal_.GetValue(0);
756	        AscendC::PipeBarrier<PIPE_ALL>();
757	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
758	
759	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
760	        return invRms;
761	    }
762	
763	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
764	    {
765	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
766	        xInLocal_ = xInQueue_.DeQue<dataType>();
767	        gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
768	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
769	        PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
770	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
771	        AscendC::Muls(yLocal_, xLocal_, invRms, validN);
772	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, validN);
773	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
774	        xInQueue_.FreeTensor(xInLocal_);
775	        gammaInQueue_.FreeTensor(gammaInLocal_);
776	        yOutQueue_.EnQue(yOutLocal_);
777	    }
778	
779	    __aicore__ inline void ProcessRow(int rowIdx)
780	    {
781	        float invRms = ComputeInvRms(rowIdx);
782	        CopyOutInvRms(rowIdx);
783	
784	        for (int by = 0; by < NumTiles(); ++by) {
785	            const int colBase = by * kBlockN;
786	            const int validN = GetValidN(colBase);
787	
788	            CopyInX(rowIdx, colBase, validN);
789	            CopyInGamma(colBase, validN);
790	            ComputeTile(invRms, validN);
791	            CopyOutY(rowIdx, colBase, validN);
792	        }
793	    }
794	
795	private:
796	    AscendC::TQue<AscendC::TPosition::VECIN, 1> xInQueue_;
797	    AscendC::TQue<AscendC::TPosition::VECIN, 1> gammaInQueue_;
798	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yOutQueue_;
799	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> invRmsOutQueue_;
800	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
801	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
802	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
803	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
804	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
805	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
806	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
807	
808	    AscendC::LocalTensor<dataType> xInLocal_;
809	    AscendC::LocalTensor<dataType> gammaInLocal_;
810	    AscendC::LocalTensor<dataType> yOutLocal_;
811	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
812	    AscendC::LocalTensor<float> invRmsLocal_;
813	    AscendC::LocalTensor<float> xLocal_;
814	    AscendC::LocalTensor<float> gammaLocal_;
815	    AscendC::LocalTensor<float> yLocal_;
816	    AscendC::LocalTensor<float> reduceLocal_;
817	    AscendC::LocalTensor<float> sumLocal_;
818	    AscendC::LocalTensor<float> tempLocal_;
819	};
820	
821	// =========================================================================
822	// Shared dtype-dispatch helper — eliminates the duplicated if/else-if/else chains
823	// in the three kernel entry points below.
824	// =========================================================================
825	
826	template <template <typename> class Kernel, typename... ExtraArgs>
827	__aicore__ inline void DispatchRmsNorm(
828	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
829	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
830	    int32_t tasksPerCore, float eps, float invN,
831	    int64_t dtypeFlag, ExtraArgs... extraArgs)
832	{
833	    if (dtypeFlag == 0) {
834	        Kernel<float> kernel;
835	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
836	        kernel.Process();
837	    } else if (dtypeFlag == 1) {
838	        Kernel<half> kernel;
839	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
840	        kernel.Process();
841	    } else {
842	        Kernel<bfloat16_t> kernel;
843	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
844	        kernel.Process();
845	    }
846	}
847	
848	// =========================================================================
849	// Kernel entry points — Abs-style: single __global__ per strategy with dtype dispatch
850	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
851	// =========================================================================
852	
853	extern "C" __global__ __aicore__ void rms_norm_merge_n(
854	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
855	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
856	    int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
857	    int64_t dtypeFlag)
858	{
859	    DispatchRmsNorm<RmsNormMergeNKernel>(
860	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
861	        eps, invN, dtypeFlag, rowFactor);
862	}
863	
864	extern "C" __global__ __aicore__ void rms_norm_single_row(
865	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
866	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
867	    int32_t tasksPerCore, float eps, float invN,
868	    int64_t dtypeFlag)
869	{
870	    DispatchRmsNorm<RmsNormSingleRowKernel>(
871	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
872	        eps, invN, dtypeFlag);
873	}
874	
875	extern "C" __global__ __aicore__ void rms_norm_splitd(
876	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
877	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
878	    int32_t tasksPerCore, float eps, float invN,
879	    int64_t dtypeFlag)
880	{
881	    DispatchRmsNorm<RmsNormSplitDKernel>(
882	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
883	        eps, invN, dtypeFlag);
884	}
