// Cumsum op_host — tiling calculation + EXEC_KERNEL_CMD launch.
// Receives float32 2D tensors (host wrapper handles dtype conversion).

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_cumsum_custom.h"

namespace ascend_kernel {

at::Tensor cumsum(const at::Tensor &x, int64_t dim)
{
    TORCH_CHECK(x.dim() == 2, "x must be 2-D [outer, inner]");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int32_t outer = static_cast<int32_t>(x.sizes()[0]);
    int32_t inner = static_cast<int32_t>(x.sizes()[1]);

    // Tiling: distribute rows (outer) across AI cores.
    int32_t aivCoreNum = static_cast<int32_t>(
        platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAiv());
    if (aivCoreNum <= 0) { aivCoreNum = 1; }
    int32_t usedCoreNum = std::min<int32_t>(aivCoreNum, std::max<int32_t>(1, outer));
    int32_t tasksPerCore = (outer + usedCoreNum - 1) / usedCoreNum;

    at::Tensor y = at::empty_like(x);

    // All tiling params as named left values (required by EXEC_KERNEL_CMD).
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(cumsum_custom, blockDim, x, y,
                    outer, inner, usedCoreNum, tasksPerCore);

    return y;
}

}  // namespace ascend_kernel
