// Cumsum AscendC kernel — chunked row-wise prefix sum on float32.
// The host wrapper handles dtype conversion (half/bf16 → float32).
// Each AI core processes tasksPerCore rows; within each core, rows are
// processed chunk-by-chunk with a scalar running accumulator between chunks.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t CHUNK_SIZE = 2048;  // Elements per chunk

// ---------------------------------------------------------------------------
// Data-move helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Cumsum kernel class (float32 only)
// =========================================================================

class CumsumKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t outer, int32_t inner,
        int32_t usedCoreNum, int32_t tasksPerCore)
    {
        this->outer = outer;
        this->inner = inner;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x),
                             static_cast<uint64_t>(outer) * inner);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y),
                             static_cast<uint64_t>(outer) * inner);

        pipe.InitBuffer(inQueueX_, BUFFER_NUM, CHUNK_SIZE * sizeof(float));
        pipe.InitBuffer(outQueue_, BUFFER_NUM, CHUNK_SIZE * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int rowIdx = coreIdx * tasksPerCore + localIdx;
                if (rowIdx < outer) {
                    ProcessRow(rowIdx);
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        int32_t numChunks = (inner + CHUNK_SIZE - 1) / CHUNK_SIZE;

        for (int32_t c = 0; c < numChunks; ++c) {
            int32_t chunkStart = c * CHUNK_SIZE;
            int32_t chunkSize = (chunkStart + CHUNK_SIZE <= inner)
                                    ? CHUNK_SIZE
                                    : (inner - chunkStart);

            // CopyIn: load one chunk from GM to UB
            AscendC::LocalTensor<float> srcLocal = inQueueX_.AllocTensor<float>();
            LoadGmToUb(srcLocal,
                       xGM_[static_cast<uint64_t>(rowIdx) * inner + chunkStart],
                       static_cast<uint32_t>(chunkSize));
            inQueueX_.EnQue(srcLocal);

            // Compute: serial prefix sum within chunk with running accumulator
            AscendC::LocalTensor<float> dstLocal = outQueue_.AllocTensor<float>();
            AscendC::LocalTensor<float> srcIn = inQueueX_.DeQue<float>();
            AscendC::PipeBarrier<PIPE_MTE2>();

            // First element: carries the running accumulator from previous chunks
            float acc = srcIn.GetValue(0);
            dstLocal.SetValue(0, acc);

            // Remaining elements in chunk
            for (int32_t j = 1; j < chunkSize; ++j) {
                acc = acc + srcIn.GetValue(j);
                dstLocal.SetValue(j, acc);
            }

            outQueue_.EnQue<float>(dstLocal);
            inQueueX_.FreeTensor(srcIn);

            // CopyOut: write one chunk from UB to GM
            AscendC::LocalTensor<float> dstOut = outQueue_.DeQue<float>();
            StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * inner + chunkStart],
                        dstOut,
                        static_cast<uint32_t>(chunkSize));
            outQueue_.FreeTensor(dstOut);
        }
    }

private:
    int32_t outer = 0;
    int32_t inner = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<float> xGM_;
    AscendC::GlobalTensor<float> yGM_;

    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inQueueX_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outQueue_;
};

// ---------------------------------------------------------------------------
// Kernel entry point
// ---------------------------------------------------------------------------

extern "C" __global__ __aicore__ void cumsum_custom(
    GM_ADDR x, GM_ADDR y,
    int32_t outer, int32_t inner,
    int32_t usedCoreNum, int32_t tasksPerCore)
{
    CumsumKernel kernel;
    kernel.Init(x, y, outer, inner, usedCoreNum, tasksPerCore);
    kernel.Process();
}
